package com.gameaggregator.contractservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.contractservice.application.ContractService;import com.gameaggregator.contractservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/contracts") public class ContractController{final ContractService s;public ContractController(ContractService s){this.s=s;}@PostMapping ApiResponse<Contract> create(@Valid @RequestBody ContractDtos.Create r){return ApiResponse.success(s.create(r));}@GetMapping ApiResponse<List<Contract>> list(){return ApiResponse.success(s.list());}@GetMapping("/{id}")ApiResponse<Contract> get(@PathVariable UUID id){return ApiResponse.success(s.get(id));}@PostMapping("/{id}/parties")ApiResponse<ContractParty> party(@PathVariable UUID id,@Valid @RequestBody ContractDtos.Party r){return ApiResponse.success(s.party(id,r));}@GetMapping("/{id}/parties")ApiResponse<List<ContractParty>> parties(@PathVariable UUID id){return ApiResponse.success(s.parties(id));}@PostMapping("/{id}/versions")ApiResponse<ContractVersion> version(@PathVariable UUID id,@Valid @RequestBody ContractDtos.Version r){return ApiResponse.success(s.version(id,r));}@GetMapping("/{id}/versions")ApiResponse<List<ContractVersion>> versions(@PathVariable UUID id){return ApiResponse.success(s.versions(id));}@PostMapping("/versions/{id}/approve")ApiResponse<ContractVersion> approve(@PathVariable UUID id,@Valid @RequestBody ContractDtos.Approval r){return ApiResponse.success(s.approve(id,r));}@PostMapping("/{id}/terminate")ApiResponse<Contract> terminate(@PathVariable UUID id,@Valid @RequestBody ContractDtos.Termination r){return ApiResponse.success(s.terminate(id,r));}}